class Solution {
public:
    int countSuffix(vector<int>& nums, vector<int>& target) {
        int n = nums.size();
        // 1) prefix equality
        vector<char> pref(n);
        pref[0] = (nums[0] == target[0]);
        for (int i = 1; i < n; ++i)
            pref[i] = pref[i-1] && (nums[i] == target[i]);

        // 2) suffix non‑increasing in target
        vector<char> sufInc(n);
        sufInc[n-1] = 1;
        for (int i = n-2; i >= 0; --i)
            sufInc[i] = (target[i] >= target[i+1]) && sufInc[i+1];

        // 3) suffix multiset equality using frequency difference
        int maxVal = 0;
        for (int v : nums) if (v > maxVal) maxVal = v;
        for (int v : target) if (v > maxVal) maxVal = v;
        vector<int> diff(maxVal + 1, 0);
        int nonZero = 0;
        vector<char> good(n);
        auto add = [&](int x, int delta) {
            int before = diff[x];
            int after = before + delta;
            if (before == 0 && after != 0) ++nonZero;
            else if (before != 0 && after == 0) --nonZero;
            diff[x] = after;
        };
        for (int i = n-1; i >= 0; --i) {
            add(nums[i], +1);
            add(target[i], -1);
            good[i] = (nonZero == 0);
        }

        // 4) count valid indices
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            bool prefixOk = (i == 0) ? true : pref[i-1];
            if (prefixOk && sufInc[i] && good[i]) ++ans;
        }
        return ans;
    }
};
